        IF startRisingEdge THEN
            stepNumber := 1;
            actionInProgress := FALSE;
        END_IF;

        CASE stepNumber OF
            1:
                MoveDown := TRUE;
                actionInProgress := TRUE;
                IF DownLimitSwitch THEN
                    MoveDown := FALSE;
                    actionInProgress := FALSE;
                    stepNumber := 2;
                END_IF;
            2:
                ActivateGrip := TRUE;
                actionInProgress := TRUE;
                IF GripLimitSwitch THEN
                    ActivateGrip := FALSE;
                    actionInProgress := FALSE;
                    stepNumber := 3;
                END_IF;
            3:
                MoveUp := TRUE;
                actionInProgress := TRUE;
                IF UpLimitSwitch THEN
                    MoveUp := FALSE;
                    actionInProgress := FALSE;
                    stepNumber := 4;
                END_IF;
            4:
                MoveRight := TRUE;
                actionInProgress := TRUE;
                IF RightLimitSwitch THEN
                    MoveRight := FALSE;
                    actionInProgress := FALSE;
                    stepNumber := 5;
                END_IF;
            5:
                MoveDown := TRUE;
                actionInProgress := TRUE;
                IF DownLimitSwitch THEN
                    MoveDown := FALSE;
                    actionInProgress := FALSE;
                    stepNumber := 6;
                END_IF;
            6:
                ActivateRelease := TRUE;
